import {
  ChevronRight,
  FolderGit2,
  FolderPlus,
  LayoutDashboard,
  PanelLeftClose,
  Plus,
  Search,
  Settings2,
} from "lucide-react";
import { useCallback, useEffect, useMemo, useRef, useState } from "react";

import { combineActivitySummaries, type ActivitySummary } from "../lib/activity";
import { cn } from "../lib/cn";
import { isMacShortcutPlatform, shortcutLabel } from "../lib/shortcuts";
import type { RegisteredProject } from "../lib/tauri";
import { worktreeIdentity, type ActiveAgent, type DirtyState, type Worktree } from "../lib/types";
import { IconButton } from "./ui/IconButton";
import { SectionHeader } from "./ui/SectionHeader";
import { StatusDot } from "./ui/StatusDot";
import { WorktreeList } from "./WorktreeList";

export const SIDEBAR_WIDTH_STORAGE_KEY = "orca.sidebar.width";
export const SIDEBAR_COLLAPSED_PROJECTS_STORAGE_KEY = "rorca.sidebar.collapsedProjects";
const DEFAULT_SIDEBAR_WIDTH = 236;
const MIN_SIDEBAR_WIDTH = 220;
const MAX_SIDEBAR_WIDTH = 420;

type SidebarProps = {
  open?: boolean;
  isMac?: boolean;
  projects?: RegisteredProject[];
  activeProjectId?: string;
  worktrees: Worktree[];
  agents: ActiveAgent[];
  activePath: string;
  statuses?: Record<string, DirtyState | undefined>;
  unreadWorktreePaths?: Record<string, boolean>;
  activityByWorktreePath?: Record<string, ActivitySummary | undefined>;
  onSelectProject?: (project: RegisteredProject) => void;
  onAddProject?: () => void;
  onSelectWorktree: (worktree: Worktree) => void;
  onCreateWorktree: () => void;
  onRefreshWorktreeStatus?: (worktree: Worktree) => void;
  onDeleteWorktree?: (worktree: Worktree) => void;
  onOpenCommandPalette: () => void;
  onOpenSettings?: () => void;
  onToggle?: () => void;
  onHide?: () => void;
};

export function Sidebar({
  open = true,
  isMac = isMacShortcutPlatform(),
  projects = [],
  activeProjectId,
  worktrees,
  agents,
  activePath,
  statuses = {},
  unreadWorktreePaths,
  activityByWorktreePath,
  onSelectProject = () => undefined,
  onAddProject = () => undefined,
  onSelectWorktree,
  onCreateWorktree,
  onRefreshWorktreeStatus = () => undefined,
  onDeleteWorktree = () => undefined,
  onOpenCommandPalette,
  onOpenSettings,
  onToggle,
  onHide,
}: SidebarProps) {
  const worktreeRegionRef = useRef<HTMLDivElement>(null);
  const dragRef = useRef<{ startX: number; startWidth: number } | null>(null);
  const [width, setWidth] = useState(loadSidebarWidth);
  const widthRef = useRef(width);
  widthRef.current = width;

  // Accordion state is stored as the set of *collapsed* projects, so each project keeps its own
  // open/closed state and toggling one never disturbs another. Projects the user has never
  // toggled default to collapsed unless they are the active project.
  const [collapsedProjects, setCollapsedProjects] = useState<Set<string>>(() => {
    const stored = loadCollapsedProjects();
    // Once the user has toggled anything the persisted set is authoritative; only a first run
    // (nothing persisted) falls back to "everything but the active project starts collapsed".
    return stored ?? seedCollapsedProjects(new Set<string>(), projects, activeProjectId);
  });
  const knownProjectsRef = useRef<Set<string>>(new Set(projects.map((project) => project.workspaceId)));

  useEffect(() => {
    // Projects registered after mount inherit the same default as the initial seed.
    const unseen = projects.filter((project) => !knownProjectsRef.current.has(project.workspaceId));
    if (unseen.length === 0) return;
    for (const project of unseen) knownProjectsRef.current.add(project.workspaceId);
    setCollapsedProjects((current) => seedCollapsedProjects(current, unseen, activeProjectId));
  }, [activeProjectId, projects]);

  const toggleProject = useCallback((workspaceId: string) => {
    setCollapsedProjects((current) => {
      const next = new Set(current);
      if (next.has(workspaceId)) next.delete(workspaceId);
      else next.add(workspaceId);
      persistCollapsedProjects(next);
      return next;
    });
  }, []);

  const worktreesByProject = useMemo(
    () => groupWorktreesByProject(worktrees, projects, activeProjectId),
    [activeProjectId, projects, worktrees],
  );

  useEffect(() => {
    const handlePointerMove = (event: PointerEvent) => {
      const drag = dragRef.current;
      if (!drag) return;
      const nextWidth = clampSidebarWidth(drag.startWidth + event.clientX - drag.startX);
      widthRef.current = nextWidth;
      setWidth(nextWidth);
    };

    const finishDrag = () => {
      if (!dragRef.current) return;
      dragRef.current = null;
      persistSidebarWidth(widthRef.current);
      document.body.style.cursor = "";
    };

    window.addEventListener("pointermove", handlePointerMove);
    window.addEventListener("pointerup", finishDrag);
    window.addEventListener("pointercancel", finishDrag);
    return () => {
      window.removeEventListener("pointermove", handlePointerMove);
      window.removeEventListener("pointerup", finishDrag);
      window.removeEventListener("pointercancel", finishDrag);
      document.body.style.cursor = "";
    };
  }, []);

  const focusWorktrees = () => {
    worktreeRegionRef.current?.focus();
    worktreeRegionRef.current?.scrollIntoView?.({ block: "start" });
  };

  const startResize = (event: React.PointerEvent<HTMLDivElement>) => {
    event.preventDefault();
    dragRef.current = { startX: event.clientX, startWidth: widthRef.current };
    document.body.style.cursor = "col-resize";
  };

  if (!open) {
    return null;
  }

  return (
    <aside
      className="relative flex h-full shrink-0 flex-col overflow-hidden bg-worktree-sidebar text-worktree-sidebar-foreground"
      style={{ width: `${width}px`, minWidth: `${MIN_SIDEBAR_WIDTH}px`, maxWidth: `${MAX_SIDEBAR_WIDTH}px` }}
    >
      <div
        data-testid="sidebar-drag-region"
        data-tauri-drag-region
        className="drag-region flex h-titlebar shrink-0 items-center px-2"
      >
        {isMac ? <div data-testid="titlebar-traffic-light-pad" className="w-[72px] shrink-0" aria-hidden="true" /> : null}
        <IconButton
          label="Hide sidebar"
          className="no-drag"
          size="sm"
          onClick={onToggle ?? onHide}
        >
          <PanelLeftClose className="size-3.5" />
        </IconButton>
      </div>

      <div className="space-y-1 px-2 pb-1">
        <button
          type="button"
          onClick={focusWorktrees}
          className="flex h-7 w-full items-center gap-2 rounded-md bg-worktree-sidebar-accent px-2 text-left text-[13px] font-medium tracking-tight text-worktree-sidebar-accent-foreground"
        >
          <LayoutDashboard className="size-3.5" />
          <span className="flex-1">Workspace</span>
        </button>
        <button
          type="button"
          onClick={onOpenCommandPalette}
          className="group relative flex h-7 w-full items-center rounded-md border border-worktree-sidebar-border/70 bg-worktree-sidebar-foreground/5 pl-7 pr-1.5 text-left text-[12px] font-medium tracking-tight text-worktree-sidebar-foreground/45 transition-colors hover:border-worktree-sidebar-border hover:bg-worktree-sidebar-foreground/8"
        >
          <Search className="pointer-events-none absolute left-2 top-1/2 size-3 -translate-y-1/2 text-worktree-sidebar-foreground/30" />
          Search workspaces
          <kbd className="ml-auto rounded border border-worktree-sidebar-border/80 bg-worktree-sidebar-foreground/8 px-1 py-px text-[9px] text-worktree-sidebar-foreground/55">
            {shortcutLabel("commandPalette.open")}
          </kbd>
        </button>
      </div>

      <div ref={worktreeRegionRef} tabIndex={-1} data-testid="worktree-region" className="flex min-h-0 flex-1 flex-col outline-none">
        <SectionHeader
          title="Projects"
          count={projects.length}
          actions={
            <>
              <IconButton label="Add worktree" size="sm" onClick={onCreateWorktree}>
                <FolderPlus className="size-3.5" />
              </IconButton>
              <IconButton label="Add project" size="sm" onClick={onAddProject}>
                <Plus className="size-3.5" />
              </IconButton>
            </>
          }
        />

        <div className="min-h-0 flex-1 overflow-y-auto overflow-x-hidden px-2 pb-2 scrollbar-sleek">
          {projects.length === 0 ? (
            <p className="px-2 py-3 text-[11px] leading-relaxed text-muted-foreground">
              No projects registered yet.
            </p>
          ) : null}

          {projects.map((project) => {
            const active = project.workspaceId === activeProjectId;
            const expanded = !collapsedProjects.has(project.workspaceId);
            const projectWorktrees = worktreesByProject.get(project.workspaceId) ?? [];
            const projectActivity = summarizeProjectActivity(
              projectWorktrees,
              activityByWorktreePath,
              unreadWorktreePaths,
            );
            const attentionState = projectActivity.hasWaiting
              ? "waiting"
              : projectActivity.hasUnread
                ? "unread"
                : null;

            return (
              <div key={project.workspaceId} className="pb-0.5">
                <div
                  className={cn(
                    "flex h-7 w-full items-center gap-0.5 rounded-md pr-1.5 transition-colors",
                    active
                      ? "bg-worktree-sidebar-accent font-medium text-worktree-sidebar-accent-foreground"
                      : "text-worktree-sidebar-foreground/65 hover:bg-worktree-sidebar-accent/60 hover:text-worktree-sidebar-foreground",
                  )}
                >
                  <button
                    type="button"
                    onClick={() => toggleProject(project.workspaceId)}
                    aria-expanded={expanded}
                    aria-label={`${expanded ? "Collapse" : "Expand"} ${project.workspaceId}`}
                    className="flex size-5 shrink-0 items-center justify-center rounded-sm text-muted-foreground transition-colors hover:text-worktree-sidebar-foreground focus-visible:outline-none focus-visible:ring-1 focus-visible:ring-ring"
                  >
                    <ChevronRight
                      aria-hidden="true"
                      className={cn("size-3 shrink-0 transition-transform", expanded && "rotate-90")}
                    />
                  </button>
                  <button
                    type="button"
                    onClick={() => onSelectProject(project)}
                    aria-current={active ? "true" : undefined}
                    aria-label={project.workspaceId}
                    className="flex min-w-0 flex-1 items-center gap-1.5 rounded-sm py-1 text-left text-[12px] focus-visible:outline-none focus-visible:ring-1 focus-visible:ring-ring"
                  >
                    <FolderGit2 className="size-3.5 shrink-0" />
                    <span className="min-w-0 flex-1 truncate">{project.workspaceId}</span>
                    {projectActivity.runningCount > 0 ? (
                      <span
                        data-testid="project-running-badge"
                        className="shrink-0 rounded-full bg-status-working/12 px-1.5 py-px text-[9px] font-medium leading-none text-status-working"
                      >
                        {projectActivity.runningCount} running
                      </span>
                    ) : null}
                    {attentionState ? (
                      <span
                        data-testid="project-attention-indicator"
                        data-attention-state={attentionState}
                        title={attentionState === "waiting" ? "Agent needs attention" : "Unread activity"}
                        className="inline-flex size-3 shrink-0 items-center justify-center"
                      >
                        <StatusDot state={attentionState} />
                      </span>
                    ) : null}
                  </button>
                </div>

                {expanded ? (
                  <div className="pl-3 pr-0.5 pt-0.5">
                    <WorktreeList
                      worktrees={projectWorktrees}
                      agents={agents}
                      activePath={active ? activePath : ""}
                      statuses={statuses}
                      unreadWorktreePaths={unreadWorktreePaths}
                      activityByWorktreePath={activityByWorktreePath}
                      onSelect={onSelectWorktree}
                      onCreate={onCreateWorktree}
                      onRefreshStatus={onRefreshWorktreeStatus}
                      onDelete={onDeleteWorktree}
                      label={`${project.workspaceId} worktrees`}
                    />
                  </div>
                ) : null}
              </div>
            );
          })}
        </div>
      </div>

      <div className="flex shrink-0 items-center justify-between border-t border-worktree-sidebar-border px-2 py-1.5">
        <div className="flex items-center gap-2 px-1 text-[10px] text-muted-foreground">
          <span className="size-1.5 rounded-full bg-status-success" />
          Local runtime
        </div>
        <IconButton label="Settings" size="sm" onClick={onOpenSettings}>
          <Settings2 className="size-3.5" />
        </IconButton>
      </div>

      <div
        role="separator"
        aria-label="Resize sidebar"
        aria-orientation="vertical"
        aria-valuemin={MIN_SIDEBAR_WIDTH}
        aria-valuemax={MAX_SIDEBAR_WIDTH}
        aria-valuenow={width}
        onPointerDown={startResize}
        className="no-drag absolute inset-y-0 right-0 z-30 w-1.5 cursor-col-resize touch-none"
      >
        <span className="pointer-events-none absolute inset-y-0 right-0 w-px bg-worktree-sidebar-border transition-colors group-hover:bg-ring/45" />
      </div>
    </aside>
  );
}

function summarizeProjectActivity(
  worktrees: Worktree[],
  activityByWorktreePath: Record<string, ActivitySummary | undefined> | undefined,
  unreadWorktreePaths: Record<string, boolean> | undefined,
): ActivitySummary {
  const summaries = worktrees
    .map((worktree) => activityByWorktreePath?.[worktree.path])
    .filter((summary): summary is ActivitySummary => Boolean(summary));
  const hasUnread = worktrees.some((worktree) => Boolean(unreadWorktreePaths?.[worktree.path]));
  return combineActivitySummaries(summaries, hasUnread);
}

/**
 * Worktrees carry their owning project inside their `orca/<wsId>/<slug>` branch name. Anything
 * without a matching registered project belongs to the active project, which is the only project
 * whose worktrees the workspace store actually holds.
 */
function groupWorktreesByProject(
  worktrees: Worktree[],
  projects: RegisteredProject[],
  activeProjectId: string | undefined,
) {
  const grouped = new Map<string, Worktree[]>();
  for (const project of projects) grouped.set(project.workspaceId, []);

  for (const worktree of worktrees) {
    const ownerId = worktreeIdentity(worktree)?.wsId;
    const owner = ownerId && grouped.has(ownerId) ? ownerId : activeProjectId;
    if (!owner) continue;
    const bucket = grouped.get(owner);
    if (bucket) bucket.push(worktree);
  }

  return grouped;
}

function seedCollapsedProjects(
  collapsed: Set<string>,
  projects: RegisteredProject[],
  activeProjectId: string | undefined,
) {
  const seeded = projects.filter(
    (project) => project.workspaceId !== activeProjectId && !collapsed.has(project.workspaceId),
  );
  if (seeded.length === 0) return collapsed;
  const next = new Set(collapsed);
  for (const project of seeded) next.add(project.workspaceId);
  return next;
}

/** Returns `null` when the accordion has never been persisted, so callers can apply defaults. */
function loadCollapsedProjects(): Set<string> | null {
  try {
    const raw = window.localStorage.getItem(SIDEBAR_COLLAPSED_PROJECTS_STORAGE_KEY);
    if (!raw) return null;
    const parsed: unknown = JSON.parse(raw);
    if (!Array.isArray(parsed)) return null;
    return new Set(parsed.filter((id): id is string => typeof id === "string"));
  } catch {
    return null;
  }
}

function persistCollapsedProjects(collapsed: Set<string>) {
  try {
    window.localStorage.setItem(SIDEBAR_COLLAPSED_PROJECTS_STORAGE_KEY, JSON.stringify([...collapsed]));
  } catch {
    // A storage failure should not break accordion toggling for this session.
  }
}

function loadSidebarWidth() {
  try {
    const stored = Number(window.localStorage.getItem(SIDEBAR_WIDTH_STORAGE_KEY));
    return Number.isFinite(stored) && stored > 0 ? clampSidebarWidth(stored) : DEFAULT_SIDEBAR_WIDTH;
  } catch {
    return DEFAULT_SIDEBAR_WIDTH;
  }
}

function persistSidebarWidth(width: number) {
  try {
    window.localStorage.setItem(SIDEBAR_WIDTH_STORAGE_KEY, String(clampSidebarWidth(width)));
  } catch {
    // A storage failure should not break pointer resizing for this session.
  }
}

function clampSidebarWidth(width: number) {
  return Math.min(MAX_SIDEBAR_WIDTH, Math.max(MIN_SIDEBAR_WIDTH, Math.round(width)));
}

import {
  Columns2,
  Globe,
  ListX,
  PanelLeftClose,
  PanelRightClose,
  Pencil,
  Pin,
  PinOff,
  Plus,
  Rows2,
  TerminalSquare,
  X,
} from "lucide-react";
import React, { type ReactNode, useEffect, useRef, useState } from "react";
import { getCurrentWindow } from "@tauri-apps/api/window";

import { resolveActivityIndicator, type ActivitySummary } from "../lib/activity";
import { cn } from "../lib/cn";
import type { WorkspaceTab } from "../lib/types";
import { NewTabPopover } from "./NewTabPopover";
import { IconButton } from "./ui/IconButton";
import { StatusDot } from "./ui/StatusDot";

type TabBarProps = {
  tabs: WorkspaceTab[];
  activeTabId: string;
  onActivate: (id: string) => void;
  onClose: (id: string) => void;
  onCloseOthers?: (id: string) => void;
  onCloseToRight?: (id: string) => void;
  onCloseToLeft?: (id: string) => void;
  onReorderTabs?: (tabId: string, targetIndex: number) => void;
  onRenameTab?: (id: string, newLabel: string) => void;
  onTogglePin?: (id: string, pinned: boolean) => void;
  onSplitRight?: (tabId: string) => void;
  onSplitDown?: (tabId: string) => void;
  onAdd: () => void;
  onAddBrowser?: (url?: string) => void;
  actions?: ReactNode;
  showAdd?: boolean;
  leadingSpacer?: number;
  unreadTabIds?: Record<string, boolean>;
  activityByTabId?: Record<string, ActivitySummary | undefined>;
};

type ContextMenuState = {
  tabId: string;
  x: number;
  y: number;
} | null;

type DropTarget = { index: number; edge: "left" | "right" } | null;

export function TabBar({
  tabs,
  activeTabId,
  onActivate,
  onClose,
  onCloseOthers,
  onCloseToRight,
  onCloseToLeft,
  onReorderTabs,
  onRenameTab,
  onTogglePin,
  onSplitRight,
  onSplitDown,
  onAdd,
  onAddBrowser,
  actions,
  showAdd = true,
  leadingSpacer = 0,
  unreadTabIds,
  activityByTabId,
}: TabBarProps) {
  const [isNewTabOpen, setIsNewTabOpen] = useState(false);
  const [contextMenu, setContextMenu] = useState<ContextMenuState>(null);
  const [renamingTabId, setRenamingTabId] = useState<string | null>(null);
  const [renameValue, setRenameValue] = useState("");
  const [draggedTabId, setDraggedTabId] = useState<string | null>(null);
  const [dropTarget, setDropTarget] = useState<DropTarget>(null);
  const renameCancelledRef = useRef(false);
  const draggedTabIdRef = useRef<string | null>(null);
  const dropTargetRef = useRef<DropTarget>(null);

  useEffect(() => {
    if (renamingTabId && !tabs.some((tab) => tab.id === renamingTabId)) {
      setRenamingTabId(null);
    }
    if (contextMenu && !tabs.some((tab) => tab.id === contextMenu.tabId)) {
      setContextMenu(null);
    }
  }, [contextMenu, renamingTabId, tabs]);

  const handleContextMenu = (event: React.MouseEvent, tab: WorkspaceTab) => {
    event.preventDefault();
    event.stopPropagation();
    setContextMenu({ tabId: tab.id, x: event.clientX, y: event.clientY });
  };

  const handleStartRename = (tab: WorkspaceTab) => {
    if (!onRenameTab) return;
    renameCancelledRef.current = false;
    setRenamingTabId(tab.id);
    setRenameValue(tab.label);
    setContextMenu(null);
  };

  const handleCommitRename = (tabId: string) => {
    const cancelled = renameCancelledRef.current;
    renameCancelledRef.current = false;
    if (!cancelled) {
      const label = renameValue.trim();
      if (label) onRenameTab?.(tabId, label);
    }
    setRenamingTabId(null);
  };

  const clearDragState = () => {
    draggedTabIdRef.current = null;
    dropTargetRef.current = null;
    setDraggedTabId(null);
    setDropTarget(null);
  };

  const handleDragStart = (event: React.DragEvent, tabId: string) => {
    draggedTabIdRef.current = tabId;
    dropTargetRef.current = null;
    setDropTarget(null);
    setDraggedTabId(tabId);
    event.dataTransfer.setData("text/plain", tabId);
    event.dataTransfer.effectAllowed = "move";
  };

  const handleDragOver = (event: React.DragEvent, index: number) => {
    if (!draggedTabIdRef.current || !onReorderTabs) return;
    event.preventDefault();
    event.dataTransfer.dropEffect = "move";

    const rect = event.currentTarget.getBoundingClientRect();
    const midX = rect.width > 0 ? rect.left + rect.width / 2 : 0;
    const clientX = typeof event.clientX === "number" && !Number.isNaN(event.clientX) ? event.clientX : (event.nativeEvent as any)?.clientX ?? 0;
    const isRightEdge = rect.width > 0 ? clientX >= midX : true;
    const nextTarget: Exclude<DropTarget, null> = { index, edge: isRightEdge ? "right" : "left" };
    const currentTarget = dropTargetRef.current;
    if (currentTarget?.index !== nextTarget.index || currentTarget.edge !== nextTarget.edge) {
      dropTargetRef.current = nextTarget;
      setDropTarget(nextTarget);
    }
  };

  const handleDragLeave = (event: React.DragEvent, index: number) => {
    const related = event.relatedTarget;
    if (related instanceof Node && event.currentTarget.contains(related)) return;
    if (dropTargetRef.current?.index === index) {
      dropTargetRef.current = null;
      setDropTarget(null);
    }
  };

  const handleDrop = (event: React.DragEvent, targetIndex: number) => {
    event.preventDefault();
    const sourceTabId = draggedTabIdRef.current || event.dataTransfer.getData("text/plain");
    const sourceIndex = tabs.findIndex((tab) => tab.id === sourceTabId);
    if (sourceIndex >= 0 && onReorderTabs) {
      const rect = event.currentTarget.getBoundingClientRect();
      const currentTarget = dropTargetRef.current;
      const insertAfterTarget =
        currentTarget?.index === targetIndex
          ? currentTarget.edge === "right"
          : (typeof event.clientX === "number" && !Number.isNaN(event.clientX) ? event.clientX : (event.nativeEvent as any)?.clientX ?? 0) >= rect.left + rect.width / 2;
      const insertionIndex = targetIndex + (insertAfterTarget ? 1 : 0);
      const finalIndex = Math.max(
        0,
        Math.min(tabs.length - 1, insertionIndex - (sourceIndex < insertionIndex ? 1 : 0)),
      );
      if (finalIndex !== sourceIndex) onReorderTabs(sourceTabId, finalIndex);
    }
    clearDragState();
  };

  const startWindowDrag = (event: React.PointerEvent<HTMLElement>) => {
    if (event.button !== 0) return;
    if (event.target instanceof Element && event.target.closest(".no-drag")) return;
    void getCurrentWindow().startDragging();
  };

  const contextTab = contextMenu ? tabs.find((tab) => tab.id === contextMenu.tabId) ?? null : null;
  const contextIndex = contextTab ? tabs.findIndex((tab) => tab.id === contextTab.id) : -1;

  return (
    <div
      data-testid="tab-strip"
      data-tauri-drag-region
      onPointerDown={startWindowDrag}
      className="drag-region relative flex h-tabbar shrink-0 items-stretch border-b border-border bg-card pr-1 select-none"
    >
      {leadingSpacer > 0 ? (
        <div
          data-testid="tab-strip-leading-spacer"
          style={{ width: `${leadingSpacer}px` }}
          className="shrink-0 border-r border-border"
        />
      ) : null}
      <div className="flex min-w-0 items-stretch overflow-x-auto scrollbar-none" role="tablist">
        {tabs.map((tab, index) => {
          const active = tab.id === activeTabId;
          const isUnread = Boolean(unreadTabIds?.[tab.id] && !active);
          const resolvedActivity = tab.kind === "browser" ? null : resolveActivityIndicator(activityByTabId?.[tab.id]);
          const activityIndicator =
            isUnread && (resolvedActivity === null || resolvedActivity === "done") ? "unread" : resolvedActivity;
          const isPinned = Boolean(tab.pinned);
          const isRenaming = renamingTabId === tab.id;
          const isDropLeft = dropTarget?.index === index && dropTarget.edge === "left";
          const isDropRight = dropTarget?.index === index && dropTarget.edge === "right";

          return (
            <div
              key={tab.id}
              role="tab"
              aria-selected={active}
              tabIndex={active ? 0 : -1}
              draggable={!isRenaming && Boolean(onReorderTabs)}
              onDragStart={(event) => handleDragStart(event, tab.id)}
              onDragOver={(event) => handleDragOver(event, index)}
              onDragLeave={(event) => handleDragLeave(event, index)}
              onDrop={(event) => handleDrop(event, index)}
              onDragEnd={clearDragState}
              onContextMenu={(event) => handleContextMenu(event, tab)}
              onClick={() => onActivate(tab.id)}
              onKeyDown={(event) => {
                if (event.key === "Enter" || event.key === " ") {
                  event.preventDefault();
                  onActivate(tab.id);
                }
              }}
              className={cn(
                "no-drag group relative flex min-w-tab max-w-tab cursor-pointer items-center gap-1.5 border-r border-border px-2 text-[12px] transition-colors outline-none focus-visible:ring-1 focus-visible:ring-inset focus-visible:ring-ring",
                active ? "bg-terminal text-foreground" : "bg-card text-muted-foreground hover:bg-accent/45 hover:text-foreground",
                draggedTabId === tab.id && "opacity-40",
                isDropLeft && "before:absolute before:inset-y-0 before:left-0 before:z-20 before:w-[2px] before:bg-blue-500 before:content-['']",
                isDropRight && "after:absolute after:inset-y-0 after:right-0 after:z-20 after:w-[2px] after:bg-blue-500 after:content-['']",
              )}
            >
              {tab.kind === "browser" ? (
                <Globe className="size-3 shrink-0 text-blue-400" />
              ) : activityIndicator ? (
                <span
                  data-testid={activityIndicator === "unread" ? "tab-unread-dot" : `tab-${activityIndicator}-indicator`}
                  aria-label={`Agent ${activityIndicator}`}
                  className="inline-flex size-3 shrink-0 items-center justify-center"
                >
                  <StatusDot state={activityIndicator} />
                </span>
              ) : (
                <TerminalSquare className="size-3 shrink-0" />
              )}

              {isRenaming ? (
                <input
                  type="text"
                  value={renameValue}
                  autoFocus
                  data-tab-rename-input="true"
                  onClick={(event) => event.stopPropagation()}
                  onPointerDown={(event) => event.stopPropagation()}
                  onChange={(event) => setRenameValue(event.target.value)}
                  onBlur={() => handleCommitRename(tab.id)}
                  onKeyDown={(event) => {
                    event.stopPropagation();
                    if (event.key === "Enter") {
                      event.preventDefault();
                      event.currentTarget.blur();
                    } else if (event.key === "Escape") {
                      event.preventDefault();
                      renameCancelledRef.current = true;
                      event.currentTarget.blur();
                    }
                  }}
                  className="min-w-0 flex-1 rounded border border-ring bg-background px-1 py-0.5 text-xs text-foreground outline-none"
                />
              ) : (
                <span className="min-w-0 flex-1 truncate text-left">{tab.label}</span>
              )}

              {isPinned ? <Pin className="size-2.5 shrink-0 text-muted-foreground/80" aria-label="Pinned tab" /> : null}

              {!isPinned ? (
                <span
                  role="button"
                  tabIndex={0}
                  aria-label={`Close ${tab.label}`}
                  onClick={(event) => {
                    event.stopPropagation();
                    onClose(tab.id);
                  }}
                  onKeyDown={(event) => {
                    if (event.key === "Enter" || event.key === " ") {
                      event.preventDefault();
                      event.stopPropagation();
                      onClose(tab.id);
                    }
                  }}
                  className="no-drag rounded p-0.5 text-muted-foreground opacity-0 hover:bg-muted hover:text-foreground group-hover:opacity-100 focus:opacity-100"
                >
                  <X className="size-3" />
                </span>
              ) : null}

              {active ? (
                <span data-testid="tab-active-indicator" className="pointer-events-none absolute inset-x-0 bottom-0 h-px bg-foreground" />
              ) : null}
            </div>
          );
        })}
        {showAdd ? (
          <div className="no-drag relative flex items-center shrink-0">
            <IconButton
              label="New tab"
              size="sm"
              className="no-drag my-auto ml-1"
              onClick={() => setIsNewTabOpen((previous) => !previous)}
            >
              <Plus className="size-3.5" />
            </IconButton>
            <NewTabPopover
              open={isNewTabOpen}
              onClose={() => setIsNewTabOpen(false)}
              onNewTerminal={() => {
                setIsNewTabOpen(false);
                onAdd();
              }}
              onNewBrowser={(url) => {
                setIsNewTabOpen(false);
                onAddBrowser?.(url);
              }}
            />
          </div>
        ) : null}
      </div>

      <div className="flex-1" />

      {actions ? <div className="no-drag ml-0.5 flex shrink-0 items-center gap-0.5">{actions}</div> : null}

      {contextMenu && contextTab && contextIndex >= 0 ? (
        <TabContextMenuPopup
          state={{ tab: contextTab, x: contextMenu.x, y: contextMenu.y, index: contextIndex }}
          tabs={tabs}
          canSplit={contextTab.kind !== "browser"}
          hasSplitRightHandler={Boolean(onSplitRight)}
          hasSplitDownHandler={Boolean(onSplitDown)}
          hasRenameHandler={Boolean(onRenameTab)}
          hasPinHandler={Boolean(onTogglePin)}
          hasCloseOthersHandler={Boolean(onCloseOthers)}
          hasCloseToRightHandler={Boolean(onCloseToRight)}
          hasCloseToLeftHandler={Boolean(onCloseToLeft)}
          onClose={() => setContextMenu(null)}
          onSplitRight={() => {
            onSplitRight?.(contextTab.id);
            setContextMenu(null);
          }}
          onSplitDown={() => {
            onSplitDown?.(contextTab.id);
            setContextMenu(null);
          }}
          onTogglePin={() => {
            onTogglePin?.(contextTab.id, !contextTab.pinned);
            setContextMenu(null);
          }}
          onRename={() => handleStartRename(contextTab)}
          onCloseTab={() => {
            if (!contextTab.pinned) onClose(contextTab.id);
            setContextMenu(null);
          }}
          onCloseOthers={() => {
            onCloseOthers?.(contextTab.id);
            setContextMenu(null);
          }}
          onCloseToRight={() => {
            onCloseToRight?.(contextTab.id);
            setContextMenu(null);
          }}
          onCloseToLeft={() => {
            onCloseToLeft?.(contextTab.id);
            setContextMenu(null);
          }}
        />
      ) : null}
    </div>
  );
}

type TabContextMenuPopupProps = {
  state: { tab: WorkspaceTab; x: number; y: number; index: number };
  tabs: WorkspaceTab[];
  canSplit: boolean;
  hasSplitRightHandler: boolean;
  hasSplitDownHandler: boolean;
  hasRenameHandler: boolean;
  hasPinHandler: boolean;
  hasCloseOthersHandler: boolean;
  hasCloseToRightHandler: boolean;
  hasCloseToLeftHandler: boolean;
  onClose: () => void;
  onSplitRight: () => void;
  onSplitDown: () => void;
  onTogglePin: () => void;
  onRename: () => void;
  onCloseTab: () => void;
  onCloseOthers: () => void;
  onCloseToRight: () => void;
  onCloseToLeft: () => void;
};

function TabContextMenuPopup({
  state,
  tabs,
  canSplit,
  hasSplitRightHandler,
  hasSplitDownHandler,
  hasRenameHandler,
  hasPinHandler,
  hasCloseOthersHandler,
  hasCloseToRightHandler,
  hasCloseToLeftHandler,
  onClose,
  onSplitRight,
  onSplitDown,
  onTogglePin,
  onRename,
  onCloseTab,
  onCloseOthers,
  onCloseToRight,
  onCloseToLeft,
}: TabContextMenuPopupProps) {
  const popupRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const handleOutside = (event: MouseEvent) => {
      if (popupRef.current && !popupRef.current.contains(event.target as Node)) onClose();
    };
    const handleKeyDown = (event: KeyboardEvent) => {
      if (event.key === "Escape") onClose();
    };
    window.addEventListener("mousedown", handleOutside, true);
    window.addEventListener("contextmenu", handleOutside, true);
    window.addEventListener("keydown", handleKeyDown, true);
    return () => {
      window.removeEventListener("mousedown", handleOutside, true);
      window.removeEventListener("contextmenu", handleOutside, true);
      window.removeEventListener("keydown", handleKeyDown, true);
    };
  }, [onClose]);

  const hasClosableOther = tabs.some((tab) => tab.id !== state.tab.id && !tab.pinned);
  const hasClosableToRight = tabs.slice(state.index + 1).some((tab) => !tab.pinned);
  const hasClosableToLeft = tabs.slice(0, state.index).some((tab) => !tab.pinned);
  const splitRightDisabled = !canSplit || !hasSplitRightHandler;
  const splitDownDisabled = !canSplit || !hasSplitDownHandler;
  const viewportWidth = typeof window === "undefined" ? 1024 : window.innerWidth;
  const viewportHeight = typeof window === "undefined" ? 768 : window.innerHeight;
  const left = Math.max(4, Math.min(Math.max(4, viewportWidth - 220), state.x));
  const top = Math.max(4, Math.min(Math.max(4, viewportHeight - 300), state.y));

  const menuButtonClass =
    "flex w-full items-center gap-2 rounded px-2 py-1.5 text-left text-foreground hover:bg-accent hover:text-accent-foreground disabled:cursor-not-allowed disabled:opacity-40 disabled:hover:bg-transparent";

  return (
    <div
      ref={popupRef}
      role="menu"
      aria-label="Tab context menu"
      className="no-drag fixed z-50 min-w-[13rem] select-none rounded-md border border-border bg-popover/95 p-1 text-xs text-popover-foreground shadow-xl backdrop-blur-md animate-in fade-in-50 zoom-in-95"
      style={{ left: `${left}px`, top: `${top}px` }}
      onClick={(event) => event.stopPropagation()}
      onPointerDown={(event) => event.stopPropagation()}
    >
      <div className="px-1.5 py-1 text-[10px] font-semibold uppercase tracking-wider text-muted-foreground/60">Split Pane</div>
      <button type="button" role="menuitem" disabled={splitRightDisabled} onClick={onSplitRight} className={cn(menuButtonClass, "justify-between")}>
        <div className="flex items-center gap-2">
          <Columns2 className="size-3.5 text-muted-foreground" />
          <span>Split terminal right</span>
        </div>
        <span className="font-mono text-[10px] text-muted-foreground">⌘D</span>
      </button>
      <button type="button" role="menuitem" disabled={splitDownDisabled} onClick={onSplitDown} className={cn(menuButtonClass, "justify-between")}>
        <div className="flex items-center gap-2">
          <Rows2 className="size-3.5 text-muted-foreground" />
          <span>Split terminal down</span>
        </div>
        <span className="font-mono text-[10px] text-muted-foreground">⌘⇧D</span>
      </button>

      <div className="my-1 h-px bg-border/60" />

      <button type="button" role="menuitem" disabled={!hasPinHandler} onClick={onTogglePin} className={menuButtonClass}>
        {state.tab.pinned ? <PinOff className="size-3.5 text-muted-foreground" /> : <Pin className="size-3.5 text-muted-foreground" />}
        <span>{state.tab.pinned ? "Unpin Tab" : "Pin Tab"}</span>
      </button>
      <button type="button" role="menuitem" disabled={!hasRenameHandler} onClick={onRename} className={menuButtonClass}>
        <Pencil className="size-3.5 text-muted-foreground" />
        <span>Change Title</span>
      </button>

      <div className="my-1 h-px bg-border/60" />

      <button
        type="button"
        role="menuitem"
        disabled={Boolean(state.tab.pinned)}
        onClick={onCloseTab}
        className={cn(menuButtonClass, "justify-between")}
      >
        <div className="flex items-center gap-2">
          <X className="size-3.5 text-muted-foreground" />
          <span>Close</span>
        </div>
        <span className="font-mono text-[10px] text-muted-foreground">⌘W</span>
      </button>
      <button
        type="button"
        role="menuitem"
        disabled={!hasCloseOthersHandler || !hasClosableOther}
        onClick={onCloseOthers}
        className={menuButtonClass}
      >
        <ListX className="size-3.5 text-muted-foreground" />
        <span>Close Others</span>
      </button>
      <button
        type="button"
        role="menuitem"
        disabled={!hasCloseToRightHandler || !hasClosableToRight}
        onClick={onCloseToRight}
        className={menuButtonClass}
      >
        <PanelRightClose className="size-3.5 text-muted-foreground" />
        <span>Close Tabs To The Right</span>
      </button>
      <button
        type="button"
        role="menuitem"
        disabled={!hasCloseToLeftHandler || !hasClosableToLeft}
        onClick={onCloseToLeft}
        className={menuButtonClass}
      >
        <PanelLeftClose className="size-3.5 text-muted-foreground" />
        <span>Close Tabs To The Left</span>
      </button>
    </div>
  );
}

import { Columns2, Rows2, X } from "lucide-react";
import React, { useRef, useState } from "react";

import type { ActivitySummary } from "../lib/activity";
import type { LayoutState, TabPaneLayout, TerminalSession, WorkspaceTab } from "../lib/types";
import type { PaneDirection, PaneNode } from "../state/paneTree";
import { BrowserPane } from "./BrowserPane";
import { TabBar } from "./TabBar";
import { TerminalPane } from "./TerminalPane";
import { IconButton } from "./ui/IconButton";

type TerminalSplitViewProps = {
  layout: LayoutState;
  sessions: Record<string, TerminalSession>;
  onActivateTab?: (tabId: string) => void;
  onCloseTab?: (tabId: string) => void;
  onCloseOtherTabs?: (tabId: string) => void;
  onCloseTabsToRight?: (tabId: string) => void;
  onCloseTabsToLeft?: (tabId: string) => void;
  onReorderTab?: (tabId: string, targetIndex: number) => void;
  onRenameTab?: (tabId: string, label: string) => void;
  onToggleTabPin?: (tabId: string, pinned: boolean) => void;
  onAddTab?: () => void;
  onAddBrowserTab?: (url?: string) => void;
  onNavigateBrowserTab?: (tabId: string, url: string) => void;
  onReloadBrowserTab?: (tabId: string) => void;
  onSplitPane?: (tabId: string, leafId: string, direction: PaneDirection) => void;
  onClosePane?: (tabId: string, leafId: string) => void;
  onSetRatio?: (tabId: string, path: string, ratio: number) => void;
  onSwapPanes?: (tabId: string, sourceLeafId: string, targetLeafId: string) => void;
  onFocusPane?: (tabId: string, leafId: string) => void;
  onTitleChange?: (tabId: string, title: string, sessionId?: string) => void;
  onBell?: (sessionId: string, tabId: string) => void;
  unreadTabIds?: Record<string, boolean>;
  activityByTabId?: Record<string, ActivitySummary | undefined>;
  leadingSpacer?: number;
};

export function TerminalSplitView({
  layout,
  sessions,
  onActivateTab = () => undefined,
  onCloseTab = () => undefined,
  onCloseOtherTabs,
  onCloseTabsToRight,
  onCloseTabsToLeft,
  onReorderTab,
  onRenameTab,
  onToggleTabPin,
  onAddTab = () => undefined,
  onAddBrowserTab = () => undefined,
  onNavigateBrowserTab = () => undefined,
  onReloadBrowserTab = () => undefined,
  onSplitPane = () => undefined,
  onClosePane = () => undefined,
  onSetRatio = () => undefined,
  onSwapPanes = () => undefined,
  onFocusPane = () => undefined,
  onTitleChange = () => undefined,
  onBell,
  unreadTabIds,
  activityByTabId,
  leadingSpacer = 0,
}: TerminalSplitViewProps) {
  const [draggedLeafId, setDraggedLeafId] = useState<{ tabId: string; leafId: string } | null>(null);

  const activeTab = layout.tabs.find((tab) => tab.id === layout.activeTabId) ?? layout.tabs[0] ?? null;
  const activeTabLayout = activeTab ? getTabPaneLayout(layout, activeTab) : null;
  const isBrowserTab = activeTab?.kind === "browser";

  const splitTab = (tabId: string, direction: PaneDirection) => {
    const tab = layout.tabs.find((candidate) => candidate.id === tabId);
    if (!tab || tab.kind === "browser") return;
    const tabLayout = getTabPaneLayout(layout, tab);
    const targetLeafId = tabLayout.activeLeafId ?? firstLeafId(tabLayout.root);
    if (targetLeafId) onSplitPane(tab.id, targetLeafId, direction);
  };

  return (
    <div className="relative flex flex-1 flex-col overflow-hidden bg-terminal" data-testid="terminal-layout">
      <TabBar
        tabs={layout.tabs}
        activeTabId={activeTab?.id ?? ""}
        unreadTabIds={unreadTabIds}
        activityByTabId={activityByTabId}
        onActivate={onActivateTab}
        onClose={onCloseTab}
        onCloseOthers={onCloseOtherTabs}
        onCloseToRight={onCloseTabsToRight}
        onCloseToLeft={onCloseTabsToLeft}
        onReorderTabs={onReorderTab}
        onRenameTab={onRenameTab}
        onTogglePin={onToggleTabPin}
        onSplitRight={(tabId) => splitTab(tabId, "horizontal")}
        onSplitDown={(tabId) => splitTab(tabId, "vertical")}
        onAdd={onAddTab}
        onAddBrowser={onAddBrowserTab}
        leadingSpacer={leadingSpacer}
      />

      <div className="relative min-h-0 flex-1 overflow-hidden bg-terminal">
        {!activeTab ? null : isBrowserTab ? (
          <BrowserPane
            tab={activeTab}
            visible={true}
            onNavigate={(url) => onNavigateBrowserTab(activeTab.id, url)}
            onReload={() => onReloadBrowserTab(activeTab.id)}
          />
        ) : activeTabLayout ? (
          <PaneRenderer
            node={activeTabLayout.root}
            tab={activeTab}
            tabLayout={activeTabLayout}
            sessions={sessions}
            path=""
            draggedLeafId={draggedLeafId}
            setDraggedLeafId={setDraggedLeafId}
            onSplitPane={onSplitPane}
            onClosePane={onClosePane}
            onSetRatio={onSetRatio}
            onSwapPanes={onSwapPanes}
            onFocusPane={onFocusPane}
            onTitleChange={onTitleChange}
            onBell={onBell}
          />
        ) : null}
      </div>
    </div>
  );
}

function getTabPaneLayout(layout: LayoutState, tab: WorkspaceTab): TabPaneLayout {
  const isBrowserTab = tab.kind === "browser";
  return layout.layoutsByTabId?.[tab.id] ?? {
    root: { type: "leaf", leafId: "leaf-default" },
    activeLeafId: "leaf-default",
    expandedLeafId: null,
    sessionIdsByLeafId: { "leaf-default": isBrowserTab ? "" : tab.sessionId },
  };
}

function firstLeafId(node: PaneNode): string {
  let current = node;
  while (current.type === "split") current = current.first;
  return current.leafId;
}

type PaneRendererProps = {
  node: PaneNode;
  tab: WorkspaceTab;
  tabLayout: TabPaneLayout;
  sessions: Record<string, TerminalSession>;
  path: string;
  draggedLeafId: { tabId: string; leafId: string } | null;
  setDraggedLeafId: (value: { tabId: string; leafId: string } | null) => void;
  onSplitPane: (tabId: string, leafId: string, direction: PaneDirection) => void;
  onClosePane: (tabId: string, leafId: string) => void;
  onSetRatio: (tabId: string, path: string, ratio: number) => void;
  onSwapPanes: (tabId: string, sourceLeafId: string, targetLeafId: string) => void;
  onFocusPane: (tabId: string, leafId: string) => void;
  onTitleChange: (tabId: string, title: string, sessionId?: string) => void;
  onBell?: (sessionId: string, tabId: string) => void;
};

function PaneRenderer(props: PaneRendererProps) {
  const { node, tab, tabLayout, sessions, path } = props;

  if (node.type === "leaf") {
    const defaultSessionId = tab.kind === "browser" ? "" : tab.sessionId;
    const sessionId = tabLayout.sessionIdsByLeafId[node.leafId] ?? defaultSessionId;
    const session = sessions[sessionId] ?? {
      id: sessionId,
      cwd: "",
      workspaceId: "",
      worktree: null,
      backendSessionId: null,
      lifecycle: "working" as const,
    };
    const isOnlyLeaf = tabLayout.root.type === "leaf";

    return (
      <PaneLeafView
        leafId={node.leafId}
        tab={tab}
        session={session}
        isOnlyLeaf={isOnlyLeaf}
        isActive={tabLayout.activeLeafId === node.leafId}
        draggedLeafId={props.draggedLeafId}
        setDraggedLeafId={props.setDraggedLeafId}
        onSplitPane={props.onSplitPane}
        onClosePane={props.onClosePane}
        onSwapPanes={props.onSwapPanes}
        onFocusPane={props.onFocusPane}
        onTitleChange={props.onTitleChange}
        onBell={props.onBell}
      />
    );
  }

  const isHorizontal = node.direction === "horizontal";
  const ratio = node.ratio ?? 0.5;

  return (
    <div
      className={`relative flex h-full w-full min-h-0 min-w-0 overflow-hidden ${isHorizontal ? "flex-row" : "flex-col"}`}
      data-testid="pane-split"
      data-direction={node.direction}
    >
      <div
        className="relative min-h-0 min-w-0 overflow-hidden"
        style={{ flexBasis: `${ratio * 100}%`, flexGrow: 0, flexShrink: 0 }}
      >
        <PaneRenderer {...props} node={node.first} path={path ? `${path}.first` : "first"} />
      </div>

      <PaneResizeDivider
        direction={node.direction}
        ratio={ratio}
        onRatioChange={(newRatio) => props.onSetRatio(tab.id, path, newRatio)}
      />

      <div
        className="relative min-h-0 min-w-0 flex-1 overflow-hidden"
        style={{ flexBasis: `${(1 - ratio) * 100}%`, flexGrow: 1, flexShrink: 1 }}
      >
        <PaneRenderer {...props} node={node.second} path={path ? `${path}.second` : "second"} />
      </div>
    </div>
  );
}

type PaneLeafViewProps = {
  leafId: string;
  tab: WorkspaceTab;
  session: TerminalSession;
  isOnlyLeaf: boolean;
  isActive: boolean;
  draggedLeafId: { tabId: string; leafId: string } | null;
  setDraggedLeafId: (value: { tabId: string; leafId: string } | null) => void;
  onSplitPane: (tabId: string, leafId: string, direction: PaneDirection) => void;
  onClosePane: (tabId: string, leafId: string) => void;
  onSwapPanes: (tabId: string, sourceLeafId: string, targetLeafId: string) => void;
  onFocusPane: (tabId: string, leafId: string) => void;
  onTitleChange: (tabId: string, title: string, sessionId?: string) => void;
  onBell?: (sessionId: string, tabId: string) => void;
};

function PaneLeafView({
  leafId,
  tab,
  session,
  isOnlyLeaf,
  isActive,
  draggedLeafId,
  setDraggedLeafId,
  onSplitPane,
  onClosePane,
  onSwapPanes,
  onFocusPane,
  onTitleChange,
  onBell,
}: PaneLeafViewProps) {
  const [isDragOver, setIsDragOver] = useState(false);
  const [isHoveredTop, setIsHoveredTop] = useState(false);

  const handleDragStart = (event: React.DragEvent) => {
    if (event.target instanceof Element && event.target.closest("button")) {
      event.preventDefault();
      return;
    }
    event.dataTransfer.setData("text/plain", `${tab.id}:${leafId}`);
    event.dataTransfer.effectAllowed = "move";
    setDraggedLeafId({ tabId: tab.id, leafId });
  };

  const handleDragEnd = () => {
    setDraggedLeafId(null);
    setIsDragOver(false);
  };

  const handleDragOver = (event: React.DragEvent) => {
    if (draggedLeafId && draggedLeafId.tabId === tab.id && draggedLeafId.leafId !== leafId) {
      event.preventDefault();
      event.dataTransfer.dropEffect = "move";
      setIsDragOver(true);
    }
  };

  const handleDragLeave = (event: React.DragEvent) => {
    const related = event.relatedTarget;
    if (related instanceof Node && event.currentTarget.contains(related)) return;
    setIsDragOver(false);
  };

  const handleDrop = (event: React.DragEvent) => {
    event.preventDefault();
    setIsDragOver(false);
    if (draggedLeafId && draggedLeafId.tabId === tab.id && draggedLeafId.leafId !== leafId) {
      onSwapPanes(tab.id, draggedLeafId.leafId, leafId);
    }
    setDraggedLeafId(null);
  };

  return (
    <div
      className={`relative flex h-full w-full min-h-0 min-w-0 overflow-hidden bg-terminal transition-all ${
        isDragOver ? "ring-2 ring-primary/80 ring-inset" : ""
      }`}
      data-testid="pane-leaf"
      data-leaf-id={leafId}
      onDragOver={handleDragOver}
      onDragLeave={handleDragLeave}
      onDrop={handleDrop}
      onClick={() => onFocusPane(tab.id, leafId)}
    >
      <div
        className="absolute inset-x-0 top-0 z-20 h-6"
        data-testid="pane-toolbar-hotspot"
        onMouseEnter={() => setIsHoveredTop(true)}
        onMouseLeave={(event) => {
          const related = event.relatedTarget;
          if (!(related instanceof Element) || !related.closest('[data-testid="pane-toolbar"]')) {
            setIsHoveredTop(false);
          }
        }}
      />

      <div
        draggable
        onDragStart={handleDragStart}
        onDragEnd={handleDragEnd}
        className={`pointer-events-none absolute inset-x-0 top-0 z-30 flex h-6 cursor-grab items-center justify-between border-b border-border/30 bg-background/85 px-2 text-[11px] text-muted-foreground backdrop-blur-md transition-opacity duration-150 active:cursor-grabbing select-none ${
          isHoveredTop ? "pointer-events-auto opacity-100" : "opacity-0"
        }`}
        data-testid="pane-toolbar"
        onMouseEnter={() => setIsHoveredTop(true)}
        onMouseLeave={() => setIsHoveredTop(false)}
      >
        <div className="pointer-events-none flex min-w-0 items-center gap-1.5">
          <span className="truncate text-[10px] font-medium text-muted-foreground/70">{tab.label}</span>
        </div>

        <div className="flex items-center gap-0.5">
          <IconButton
            label="Split pane right"
            size="sm"
            className="size-5 rounded p-0 text-muted-foreground/70 hover:bg-accent/60 hover:text-foreground"
            onClick={(event) => {
              event.stopPropagation();
              onSplitPane(tab.id, leafId, "horizontal");
            }}
          >
            <Columns2 className="size-3" />
          </IconButton>
          <IconButton
            label="Split pane down"
            size="sm"
            className="size-5 rounded p-0 text-muted-foreground/70 hover:bg-accent/60 hover:text-foreground"
            onClick={(event) => {
              event.stopPropagation();
              onSplitPane(tab.id, leafId, "vertical");
            }}
          >
            <Rows2 className="size-3" />
          </IconButton>
          {!isOnlyLeaf ? (
            <IconButton
              label="Close split view"
              size="sm"
              className="size-5 rounded p-0 text-muted-foreground/70 hover:bg-accent/60 hover:text-foreground"
              onClick={(event) => {
                event.stopPropagation();
                onClosePane(tab.id, leafId);
              }}
            >
              <X className="size-3" />
            </IconButton>
          ) : null}
        </div>
      </div>

      <div className="h-full w-full min-h-0 flex-1 overflow-hidden">
        <TerminalPane
          key={`${leafId}:${session.id}`}
          session={session}
          active={isActive}
          onTitleChange={(title) => onTitleChange(tab.id, title, session.id)}
          onBell={() => onBell?.(session.id, tab.id)}
        />
      </div>
    </div>
  );
}

const MIN_PANE_SIZE_PX = 80;

type PaneResizeDividerProps = {
  direction: PaneDirection;
  ratio: number;
  onRatioChange: (ratio: number) => void;
};

function PaneResizeDivider({ direction, ratio, onRatioChange }: PaneResizeDividerProps) {
  const dividerRef = useRef<HTMLDivElement>(null);
  const draggingRef = useRef(false);
  const isHorizontal = direction === "horizontal";

  const handlePointerDown = (event: React.PointerEvent) => {
    event.preventDefault();
    const parent = dividerRef.current?.parentElement;
    if (!parent) return;

    draggingRef.current = true;
    document.body.style.cursor = isHorizontal ? "col-resize" : "row-resize";
    const parentRect = parent.getBoundingClientRect();

    const handlePointerMove = (pointerEvent: PointerEvent) => {
      if (!draggingRef.current) return;
      const totalSize = isHorizontal ? parentRect.width : parentRect.height;
      if (totalSize <= 0) return;
      if (totalSize <= MIN_PANE_SIZE_PX * 2) {
        onRatioChange(0.5);
        return;
      }
      const position = isHorizontal ? pointerEvent.clientX - parentRect.left : pointerEvent.clientY - parentRect.top;
      const minimumRatio = MIN_PANE_SIZE_PX / totalSize;
      const clampedRatio = Math.max(minimumRatio, Math.min(1 - minimumRatio, position / totalSize));
      onRatioChange(Number(clampedRatio.toFixed(4)));
    };

    const handlePointerUp = () => {
      draggingRef.current = false;
      document.body.style.cursor = "";
      window.removeEventListener("pointermove", handlePointerMove);
      window.removeEventListener("pointerup", handlePointerUp);
      window.removeEventListener("pointercancel", handlePointerUp);
    };

    window.addEventListener("pointermove", handlePointerMove);
    window.addEventListener("pointerup", handlePointerUp);
    window.addEventListener("pointercancel", handlePointerUp);
  };

  return (
    <div
      ref={dividerRef}
      role="separator"
      aria-label="Resize terminal panes"
      aria-orientation={isHorizontal ? "vertical" : "horizontal"}
      aria-valuenow={Math.round(ratio * 100)}
      data-divider-hit-target="true"
      onPointerDown={handlePointerDown}
      className={`no-drag relative z-20 flex shrink-0 touch-none items-center justify-center ${
        isHorizontal ? "w-1.5 cursor-col-resize hover:bg-primary/20" : "h-1.5 cursor-row-resize hover:bg-primary/20"
      }`}
    >
      <span
        data-testid="split-divider-line"
        className={isHorizontal ? "h-full w-px bg-border/80" : "h-px w-full bg-border/80"}
      />
    </div>
  );
}

import { GitBranch, LockKeyhole, RefreshCcw, Trash2 } from "lucide-react";

import { resolveActivityIndicator, type ActivitySummary } from "../lib/activity";
import { cn } from "../lib/cn";
import { worktreeIdentity, type ActiveAgent, type DirtyState, type Worktree } from "../lib/types";
import { IconButton } from "./ui/IconButton";
import { StatusDot, type StatusDotState } from "./ui/StatusDot";

type WorktreeListProps = {
  worktrees: Worktree[];
  activePath: string;
  agents: ActiveAgent[];
  statuses: Record<string, DirtyState | undefined>;
  unreadWorktreePaths?: Record<string, boolean>;
  activityByWorktreePath?: Record<string, ActivitySummary | undefined>;
  onSelect: (worktree: Worktree) => void;
  onCreate: () => void;
  onRefreshStatus: (worktree: Worktree) => void;
  onDelete: (worktree: Worktree) => void;
  label?: string;
};

function branchName(worktree: Worktree) {
  return worktree.branch?.replace(/^refs\/heads\//, "") ?? "detached HEAD";
}

function workspaceName(worktree: Worktree) {
  const parts = branchName(worktree).split("/");
  if (parts[0] === "orca" && parts.length > 2) {
    return parts.slice(2).join("/");
  }
  const branch = branchName(worktree);
  if (branch && branch !== "detached HEAD" && branch !== "orca-lite") {
    return branch;
  }
  return "main";
}

/** The repository root worktree is the one that is not an `orca/<ws>/<slug>` worktree branch. */
function isPrimaryWorktree(worktree: Worktree) {
  return worktreeIdentity(worktree) === null;
}

export function WorktreeList({
  worktrees,
  activePath,
  agents,
  statuses,
  unreadWorktreePaths,
  activityByWorktreePath,
  onSelect,
  onCreate,
  onRefreshStatus,
  onDelete,
  label = "Worktrees",
}: WorktreeListProps) {
  if (worktrees.length === 0) {
    return (
      <div className="border-l border-worktree-sidebar-border py-2 pl-3 pr-2 text-[11px] leading-relaxed text-muted-foreground">
        <p>No Git worktrees found for this repository.</p>
        <button
          type="button"
          onClick={onCreate}
          className="mt-1 rounded-sm text-[11px] font-medium text-worktree-sidebar-foreground/70 underline-offset-2 transition-colors hover:text-worktree-sidebar-foreground hover:underline focus-visible:outline-none focus-visible:ring-1 focus-visible:ring-ring"
        >
          Create the first worktree
        </button>
      </div>
    );
  }

  return (
    <ul aria-label={label} className="m-0 list-none p-0">
      {worktrees.map((worktree) => {
        const active = worktree.path === activePath;
        const agent = agents.find((candidate) => candidate.worktreePath === worktree.path);
        const status = statuses[worktree.path];
        const primary = isPrimaryWorktree(worktree);
        const canDelete = !primary;
        const summary = activityByWorktreePath?.[worktree.path];
        const hasUnread = !active && Boolean(summary?.hasUnread || unreadWorktreePaths?.[worktree.path]);
        const displaySummary = summary ? { ...summary, hasUnread } : undefined;
        const aggregateIndicator = resolveActivityIndicator(displaySummary);
        const indicator: StatusDotState | null = aggregateIndicator ?? (summary === undefined && agent ? agent.state : null);

        return (
          <li
            key={worktree.path}
            className={cn(
              "group/worktree-row relative border-l transition-colors",
              active
                ? "border-worktree-sidebar-ring/60 bg-worktree-sidebar-accent"
                : "border-worktree-sidebar-border hover:bg-worktree-sidebar-accent/45",
            )}
          >
            <button
              type="button"
              onClick={() => onSelect(worktree)}
              aria-current={active ? "true" : undefined}
              className="w-full rounded-sm py-1.5 pl-2 pr-14 text-left focus-visible:outline-none focus-visible:ring-1 focus-visible:ring-ring"
            >
              <span className="flex min-w-0 items-start gap-1.5">
                <span className="mt-0.5 flex size-4 shrink-0 items-center justify-center text-muted-foreground">
                  <GitBranch className="size-3" />
                </span>
                <span className="min-w-0 flex-1">
                  <span className="flex items-center gap-1.5">
                    <span
                      data-testid="worktree-status-dot"
                      data-activity-state={indicator ?? "idle"}
                      className="inline-flex size-3 shrink-0 items-center justify-center"
                    >
                      {indicator ? <StatusDot state={indicator} /> : <span className="size-1.5 shrink-0 rounded-full bg-status-idle" />}
                    </span>
                    <span className="min-w-0 flex-1 truncate text-[12px] font-medium leading-tight text-foreground">
                      {workspaceName(worktree)}
                    </span>
                    {primary ? (
                      <span className="shrink-0 rounded-full bg-worktree-sidebar-foreground/10 px-1.5 py-px text-[10px] font-medium leading-none text-muted-foreground">
                        primary
                      </span>
                    ) : null}
                  </span>
                  <span className="mt-0.5 block truncate font-mono text-[9px] leading-snug text-muted-foreground/75">
                    {branchName(worktree)}
                  </span>
                  <span className={cn("mt-0.5 block text-[9px]", status?.isDirty ? "text-status-warning" : "text-muted-foreground/75")}>
                    {status ? (status.isDirty ? `Dirty · ${status.files.length} ${status.files.length === 1 ? "file" : "files"}` : "Clean") : "Status not checked"}
                  </span>
                  {agent ? (
